#include <cstdio>
#include <algorithm>
using namespace std;

int main() {
    int n, k;
    while (scanf("%d %d", &n, &k), n || k) { // Combined input check and read to streamline the process
        int sum = 0;
        int a[1000000];

        for (int i = 0; i < n; i++) {
            scanf("%d", &a[i]);
            if (i < k) sum += a[i]; // Calculate initial sum during input
        }

        int m = sum; // Initialize max with the initial sum

        for (int i = k; i < n; i++) {
            sum += a[i] - a[i - k]; // Sliding window technique
            m = max(m, sum);
        }

        printf("%d\n", m);
    }
}

